-- Publishes the actual onboarding-documents PDF (Acceptable Use Policy,
-- Disciplinary Action, Code of Ethics, Code of Conduct, and the employment NDA/CIIA,
-- already merged into one file as supplied) as the active nda_templates row, with the
-- field map derived from the real document (pixel-verified against rendered pages, not
-- guessed). This is the same effect as nda-template-publish, run directly here since
-- there is no self-service admin UI for this by design -- see NdaTemplatePage.tsx.
--
-- Deliberately excluded from the field map: the company signature block on the NDA
-- page (page_index 329) is already pre-rendered in the source PDF (Jobin Jose, COO) and
-- must never be a fillable field; the optional "prior inventions" table on Exhibit A
-- (page_index 330) is voluntary free-form disclosure, not part of the fixed field
-- vocabulary; and Exhibit B's termination certification (page_index 332) is explicitly
-- gated "DO NOT SIGN UNTIL YOU HAVE TERMINATED" in the document itself, so it is not
-- part of the onboarding-time signing session.

UPDATE nda_templates SET is_active = false, retired_at = now() WHERE is_active = true;

INSERT INTO nda_templates
    (version, label, storage_bucket, storage_path, content_sha256, byte_size,
     page_count, field_map, is_active, published_by)
